sys_transform_entry.source_script:
answer = (function transformEntry(source) {
    //Normally in EXFO Context data a segment (connection element) is a logical or physical link
    //But if we want to populate ports as segments for some reason, we can do that

    var objectSourceGR = new GlideRecord('sys_object_source');
    var matchedKey = ''; // Initialize return value

    if (source.u_segment_has_link_key) {
        objectSourceGR .addQuery('id', source.u_segment_has_link_key);
    } else if (source.u_segment_has_a_port_key) {
        objectSourceGR .addQuery('id', source.u_segment_has_a_port_key);
    } else if (source.u_segment_has_z_port_key) {
        objectSourceGR .addQuery('id', source.u_segment_has_z_port_key);
    }

    objectSourceGR.query();
    if (objectSourceGR.next()) {
        // If we found a match, get the target_sys_id instead of sys_id
        var targetSysId = objectSourceGR.getValue('target_sys_id');
        //gs.info("Found sys_object_source match with target_sys_id: " + targetSysId);
    }

  // Query sys_object_source for matching record
    objectSourceGR.query();
    if (objectSourceGR.next()) {
        // If we found a match, get the target_sys_id instead of sys_id
        var targetSysId = objectSourceGR.getValue('target_sys_id');
        //gs.info("Found sys_object_source match with target_sys_id: " + targetSysId);

        // Now query cmdb_ci based on target_sys_id from sys_object_source
        var ciGR = new GlideRecord('cmdb_ci');
        if (ciGR.get(targetSysId)) {
            //gs.info("Found cmdb_ci record with sys_id: " + targetSysId + " and name: " + ciGR.getValue('name'));

            // Now check related TNI entity records
            var tniGR = new GlideRecord('tni_entity');
            tniGR.addQuery('ci', targetSysId);
            tniGR.query();

            while (tniGR.next()) {
                returnType = tniGR.getValue('inventory_category');
                //gs.info("Found TNI entity with inventory_category: " + returnType );
            }
        } else {
            gs.info("No cmdb_ci record found for target_sys_id: " + targetSysId);
        }
    }

    return returnType;
})(source);
